INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 3000, 1, "vo_minigame_1013_icon_2_002_001", "訓練はまだ\nここからですわ", "vo_minigame_1013_icon_1_002_001", 2, 2, 1000, "調子が上がって\nきたなっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 3000, 2, "vo_minigame_1013_icon_2_003_001", "クスクス、悪くない\n流れですわね", "vo_minigame_1013_icon_1_003_001", 2, 2, 5000, "ほらほら、\nまだいけるだろ？");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 3000, 3, "vo_minigame_1013_icon_2_004_001", "すばらしい\n記録ですわ", "vo_minigame_1013_icon_1_004_001", 2, 2, 10000, "へへっ、おまえら\nやるじゃねえか！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 3000, 4, "vo_minigame_1013_icon_2_005_001", "乗りに乗って\nいますわね", "vo_minigame_1013_icon_1_005_001", 2, 3, 10000, "あたしたちはまだ\n止まらねえぜ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 3000, 5, "vo_minigame_1013_icon_2_005_002", "まだまだ行きます\nついてきなさい", "vo_minigame_1013_icon_1_005_002", 2, 3, 10000, "見てろよ！\nマコト班の快進撃だ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 3000, 6, "vo_minigame_1013_icon_2_005_003", "エリコ班の\n本領発揮ですわ！", "vo_minigame_1013_icon_1_005_003", 2, 3, 10000, "うおぉぉっ！\n絶好調だぜ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 3000, 7, "vo_minigame_1013_icon_2_006_001", "ここからは\n前人未到の領域です！", "vo_minigame_1013_icon_1_006_001", 2, 4, 0, "どこまで行けるか\n楽しみだなっ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 1000, 8, "vo_minigame_1013_icon_2_007_001", "厄介でしたわ…", "vo_minigame_1013_icon_1_007_001", 3, 5, 1, "まだ諦めんなよっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 1000, 9, "vo_minigame_1013_icon_2_007_002", "油断大敵です", "vo_minigame_1013_icon_1_007_002", 3, 5, 1, "冷やっとしたぜ…！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 1000, 10, "vo_minigame_1013_icon_2_007_003", "忌々しいっ…", "vo_minigame_1013_icon_1_007_003", 3, 5, 1, "弱音を吐くなっ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 1500, 11, "vo_minigame_1013_icon_2_008_001", "大所帯ですわね", "vo_minigame_1013_icon_1_008_001", 4, 6, 99, "マコト班集合！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 1500, 12, "vo_minigame_1013_icon_2_008_002", "エリコ班へようこそ", "vo_minigame_1013_icon_1_008_002", 4, 6, 99, "連携してくぞ！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 3000, 13, "vo_minigame_1013_icon_2_020_001", "ナナカちゃんに\nお任せあれ", "vo_minigame_1013_icon_1_020_001", 1, 8, 0, "みんなに力を！");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (7, 3000, 14, "vo_minigame_1013_icon_2_022_001", "はっはっは！\n任せろ！", "vo_minigame_1013_icon_1_022_001", 1, 9, 0, "任せてくれたまえ");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (8, 3000, 15, "vo_minigame_1013_icon_2_023_001", "どんどんいくわよ", "vo_minigame_1013_icon_1_023_001", 1, 10, 0, "ほな、いきまひょか");
